using System;using System.Collections.Concurrent;using System.Collections.Generic;using WildsEngine.Discoveries.Abstractions;using WildsEngine.Discoveries.Abstractions.Narratives;using WildsEngine.Discoveries.Abstractions.Services;using WildsEngine.Discoveries.Abstractions.Truths;
namespace WildsEngine.Discoveries.Truths { internal sealed class DiscoveryTruthSurface:IDiscoveryTruthSurface { private readonly IWildsServiceClock _clock;private readonly ConcurrentDictionary<Guid,IDiscoveryTruthProfile> _p=new();private readonly ConcurrentDictionary<Guid,IDiscoveryTruthRegistration> _r=new();public DiscoveryTruthSurface(IWildsServiceClock c){_clock=c;}public IDiscoveryTruthRegistration Register(IDiscoveryTruthProfile p){var identified=p.CongealmentPolicy as IIdentifiedTruthCongealmentPolicy??throw new ArgumentException("Truth policies must expose stable identity.");var r=new DiscoveryTruthRegistration(Guid.NewGuid(),p,identified.Id,_clock.GetUtcNow());if(!_p.TryAdd(p.Id,p)||!_r.TryAdd(r.Id,r))throw new InvalidOperationException("Truth profile already registered.");return r;}public IDiscoveryTruthCongealmentResult Congeal(IDiscoveryCompetingNarrativesResult n,Guid id,IDiscoveryVectorSeries s,IReadOnlyList<IDiscoveryCluster> c){if(!_r.TryGetValue(id,out var r)||!_p.TryGetValue(r.ProfileId,out var p))throw new KeyNotFoundException();if(n.Composition.Population.Scope!=r.Scope||s.Scope!=r.Scope)throw new InvalidOperationException("Scopes must match.");var can=p.CongealmentPolicy.CanCongeal(c,s);var truths=new List<ITruth>();if(can)truths.Add(p.CongealmentPolicy.Congeal(c,s));return new DiscoveryTruthCongealmentResult(Guid.NewGuid(),n,r,s,c,truths,can,_clock.GetUtcNow());} } }
